package com.codequest;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/admin/missions")
public class AdminMissionsServlet extends HttpServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{if(!Auth.admin(q)){p.sendRedirect("login");return;}String body="<p class='muted'>Create multiple-choice programming missions for students.</p><form method='post'><label>Title</label><input name='title' maxlength='100' required><label>Description / question</label><textarea name='description' required></textarea><label>Category</label><select name='category'><option>Java</option><option>SQL</option><option>DSA</option></select><label>Difficulty</label><select name='difficulty'><option>Easy</option><option>Medium</option><option>Hard</option></select><label>Option A</label><input name='a' required><label>Option B</label><input name='b' required><label>Option C</label><input name='c' required><label>Option D</label><input name='d' required><label>Correct answer (must exactly match one option)</label><input name='correct' required><label>XP reward</label><input type='number' name='xp' value='50' min='1' required><button>Create mission</button></form><p><a href='../missions'>View student missions</a> · <a href='../logout'>Logout</a></p>";
 p.setContentType("text/html;charset=UTF-8");p.getWriter().print(View.page("Admin · Manage Missions",body,q.getContextPath()));}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{if(!Auth.admin(q)){p.sendRedirect("login");return;}
 try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO missions(title,description,category,difficulty,option_a,option_b,option_c,option_d,correct_answer,xp_reward,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)")){s.setString(1,q.getParameter("title"));s.setString(2,q.getParameter("description"));s.setString(3,q.getParameter("category"));s.setString(4,q.getParameter("difficulty"));s.setString(5,q.getParameter("a"));s.setString(6,q.getParameter("b"));s.setString(7,q.getParameter("c"));s.setString(8,q.getParameter("d"));s.setString(9,q.getParameter("correct"));s.setInt(10,Integer.parseInt(q.getParameter("xp")));Object aid=q.getSession().getAttribute("adminId");if(!(aid instanceof Integer)){p.sendRedirect("login");return;}s.setInt(11,(Integer)aid);s.executeUpdate();p.sendRedirect("missions?created=1");}catch(Exception ex){throw new IOException(ex);}
 }
}